<style>.product-list-tools{display:flex;gap:8px;align-items:center}.admin-search,.product-list-tools select{min-height:36px;padding:7px 10px;border:1px solid #d4d4d1;border-radius:8px;background:#fff}.admin-search{width:210px}.data-table tr[hidden]{display:none}.availability-form{margin:0}.availability-toggle{border:1px solid transparent;border-radius:999px;padding:7px 11px;cursor:pointer;font:inherit;font-size:.8rem;font-weight:800}.availability-toggle.is-available{background:#e8f4df;color:#315d24;border-color:#b9d9a9}.availability-toggle.is-unavailable{background:#eee7d4;color:#6b5d49;border-color:#d9ccb0}.availability-toggle:hover{filter:brightness(.97)}@media(max-width:850px){.product-list-tools{width:100%;flex-wrap:wrap}.admin-search{flex:1;min-width:180px}.product-list-tools select{flex:1}}@media(max-width:600px){.product-list-tools{display:grid;grid-template-columns:1fr 1fr}.admin-search{grid-column:1/-1;width:100%}.product-list-tools select{width:100%}}
