<script>const ps=document.getElementById('product-search'),cf=document.getElementById('category-filter'),af=document.getElementById('availability-filter'),pe=document.getElementById('products-empty'),pc=document.getElementById('products-count');function filterProducts(){const q=ps.value.trim().toLowerCase(),cat=cf.value,f=af.value;let shown=0;document.querySelectorAll('#product-rows tr[data-search]').forEach(r=>{const ok=(!q||r.dataset.search.includes(q))&&(!cat||r.dataset.category===cat)&&(!f||r.dataset.availability===f);r.hidden=!ok;if(ok)shown++});pc.textContent=`${shown} ${shown===1?'producto':'productos'} ${q||cat||f?'encontrados':'registrados'}`;pe.hidden=shown!==0||document.querySelectorAll('#product-rows tr[data-search]').length===0}ps?.addEventListener('input',filterProducts);cf?.addEventListener('change',filterProducts);af?.addEventListener('change',filterProducts);</script>
